namespace MVZ2.Customize
{
    public class TeleporterTeamController : CustomizePageController
    {
        public override void Display(Camera camera)
        {
            isMobileLayout = Global.Game.UseMobileLayout();
            uiCamera = camera;
            LoadTeam();
            LoadBlueprints();
            gameObject.SetActive(true);
        }
        public override void Hide()
        {
            gameObject.SetActive(false);
        }
        #region 生命周期
        private void Awake()
        {
            ui.OnBlueprintPointerInteraction += OnBlueprintPointerInteractionCallback;
            ui.OnPickaxePointerEnter += OnPickaxePointerEnterCallback;
            ui.OnPickaxePointerExit += OnPickaxePointerExitCallback;
            ui.OnPickaxePointerDown += OnPickaxePointerDownCallback;
            ui.OnLayoutTilePointerInteraction += OnLayoutTilePointerInteractionCallback;
            ui.OnConfirmClick += OnConfirmClickCallback;
            ui.OnCancelClick += OnCancelClickCallback;
        }
        private void Update()
        {
            var pointerPosition = Global.Input.GetPointerScreenPosition();
            var worldPosition = GetCamera().ScreenToWorldPoint(pointerPosition);
            worldPosition.z = transform.position.z;
            ui.SetHoldingModelPosition(worldPosition);
        }
        #endregion

        #region 事件回调
        private void OnBlueprintPointerInteractionCallback(int index, PointerEventData pointerData, PointerInteraction interaction)
        {
            var pointerType = InputHelper.GetPointerType(pointerData.pointerId);
            switch (pointerType)
            {
                case PointerTypes.MOUSE:
                    HandleMouseBlueprintPointerInteraction(index, pointerData, interaction);
                    break;
                case PointerTypes.TOUCH:
                    HandleTouchBlueprintPointerInteraction(index, pointerData, interaction);
                    break;
            }
        }
        private void HandleMouseBlueprintPointerInteraction(int index, PointerEventData pointerData, PointerInteraction interaction)
        {
            switch (interaction)
            {
                case PointerInteraction.Down:
                    if (pointerData.IsMouseButNotLeft())
                        break;
                    SelectBlueprintAction(index);
                    break;
            }
        }
        private void HandleTouchBlueprintPointerInteraction(int index, PointerEventData pointerData, PointerInteraction interaction)
        {
            switch (interaction)
            {
                case PointerInteraction.BeginDrag:
                    dragBlueprintStarted = false;
                    draggingTargetBlueprintIndex = index;
                    break;
                case PointerInteraction.Drag:
                    if (!dragBlueprintStarted && Mathf.Abs(pointerData.delta.x) > Mathf.Abs(pointerData.delta.y))
                    {
                        ui.DisableBlueprintDisplayerScrollRectDragging();
                        SelectBlueprintAction(draggingTargetBlueprintIndex);
                        dragBlueprintStarted = true;
                    }
                    break;
                case PointerInteraction.EndDrag:
                    dragBlueprintStarted = false;
                    draggingTargetBlueprintIndex = -1;
                    break;
                case PointerInteraction.Click:
                    SelectBlueprintAction(index);
                    break;
            }
        }
        private void OnPickaxePointerEnterCallback(PointerEventData eventData)
        {
        }
        private void OnPickaxePointerExitCallback(PointerEventData eventData)
        {
        }
        private void OnPickaxePointerDownCallback(PointerEventData eventData)
        {
            if (eventData.IsMouseButNotLeft())
                return;
            SelectPickaxeAction();
        }
        private void OnLayoutTilePointerInteractionCallback(int index, PointerEventData pointerData, PointerInteraction interaction)
        {
            var pointerType = InputHelper.GetPointerType(pointerData.pointerId);
            switch (pointerType)
            {
                case PointerTypes.MOUSE:
                    HandleMouseLayoutTilePointerInteraction(index, pointerData, interaction);
                    break;
                case PointerTypes.TOUCH:
                    HandleTouchLayoutTilePointerInteraction(index, pointerData, interaction);
                    break;
            }
        }
        private void HandleMouseLayoutTilePointerInteraction(int index, PointerEventData pointerData, PointerInteraction interaction)
        {
            switch (interaction)
            {
                case PointerInteraction.Enter:
                    SetFocusedLayoutTileIndex(index);
                    break;
                case PointerInteraction.Exit:
                    SetFocusedLayoutTileIndex(-1);
                    break;
                case PointerInteraction.Down:
                    if (pointerData.IsMouseButNotLeft())
                        break;
                    ConfirmOnLayoutTileAction(index);
                    break;
            }
        }
        private void HandleTouchLayoutTilePointerInteraction(int index, PointerEventData pointerData, PointerInteraction interaction)
        {
            switch (interaction)
            {
                case PointerInteraction.Enter:
                    SetFocusedLayoutTileIndex(index);
                    break;
                case PointerInteraction.Exit:
                    SetFocusedLayoutTileIndex(-1);
                    break;
                case PointerInteraction.Release:
                    ConfirmOnLayoutTileAction(index);
                    break;
            }
        }
        private void OnConfirmClickCallback()
        {
            SaveTeam();
            Return();
        }
        private void OnCancelClickCallback()
        {
            Return();
        }
        #endregion

        #region 队伍
        private void LoadTeam()
        {
            var team = Global.Saves.GetTeleporterTeam() ?? DefaultTeam;
            currentTeleporterTeam = team.Clone();
            SetTeam(team);
        }
        private void SetTeam(TeleporterTeam team)
        {
            SetEnergyCost(0);
            ui.SetLayoutTileCount(MAX_TILE_COUNT);
            ui.ClearTiles();
            var tileIndexes = team.GetTileIndexes();
            foreach (var index in tileIndexes)
            {
                var tile = team.GetTile(index);
                if (tile == null)
                    continue;
                foreach (var ent in tile.GetEntities())
                {
                    var entDefinition = Global.Game.GetEntityDefinition(ent);
                    if (entDefinition == null)
                        continue;
                    var modelBuilder = GetEntityModelBuilder(entDefinition);
                    if (modelBuilder == null)
                        continue;
                    ui.AddTileEntity(index, ent, modelBuilder);
                    AddEnergyCost(entDefinition.GetCost());
                }
            }
        }

        private void SaveTeam()
        {
            Global.Saves.SetTeleporterTeam(currentTeleporterTeam);
            Global.Saves.SaveToFile();
        }
        #endregion

        #region 蓝图
        private void LoadBlueprints()
        {
            ui.SetBlueprintDisplayerPlatform(isMobileLayout);

            contraptionEntries.Clear();
            Main.AlmanacManager.GetContraptionPageEntries(contraptionEntries);

            UpdateBlueprints();
        }
        private void UpdateBlueprints()
        {
            var contraptionViewDatas = new ChoosingBlueprintViewData[contraptionEntries.Count];
            for (int i = 0; i < contraptionEntries.Count; i++)
            {
                var entry = contraptionEntries[i];
                var viewData = Main.AlmanacManager.GetChoosingBlueprintViewData(entry, false);
                if (NamespaceID.IsValid(entry))
                {
                    viewData.disabled = CannotSelectContraption(entry);
                }
                contraptionViewDatas[i] = viewData;
            }
            ui.SetBlueprintEntries(isMobileLayout, contraptionViewDatas);
        }
        private bool IsContraptionBanned(EntityDefinition definition)
        {
            if (definition.GetCost() <= 0)
                return true;
            if (definition.IsUpgradeBlueprint())
                return true;
            // TODO: 加入实现。
            //if (definition.BannedInTeleporterTeam())
            //    return true;
            return false;
        }
        private bool CannotSelectContraption(NamespaceID contraptionID)
        {
            var definition = Global.Game.GetEntityDefinition(contraptionID);
            if (definition == null)
                return true;
            if (IsContraptionBanned(definition))
                return true;
            if (definition.GetCost() > GetRemainingEnergy())
                return true;
            return false;
        }
        #endregion

        #region 手持
        private bool IsHoldingAnything()
        {
            return IsHoldingAnyBlueprint() || IsHoldingPickaxe();
        }
        private bool IsHoldingAnyBlueprint()
        {
            return holdingBlueprintIndex >= 0;
        }
        private bool IsHoldingPickaxe() => holdingPickaxe;
        private void SelectBlueprintAction(int index)
        {
            if (IsHoldingAnything())
            {
                Global.Sounds.Play2D(LogicSoundID.tap);
                CancelHolding();
            }
            else
            {
                var id = contraptionEntries[index];
                if (!NamespaceID.IsValid(id) || CannotSelectContraption(id))
                {
                    Global.Sounds.Play2D(LogicSoundID.buzzer);
                }
                else
                {
                    // TODO 实现这个
                    //Global.Sounds.Play2D(VanillaSoundID.select);
                    HoldBlueprint(index);
                }
            }
        }
        private void HoldBlueprint(int index)
        {
            holdingBlueprintIndex = index;
            holdingPickaxe = false;
            var entityID = contraptionEntries[index];
            if (!NamespaceID.IsValid(entityID))
                return;
            var entityDefinition = Global.Game.GetEntityDefinition(entityID);
            if (entityDefinition == null)
                return;
            var modelBuilder = GetEntityModelBuilder(entityDefinition);
            if (modelBuilder != null)
            {
                ui.SetHoldingModel(modelBuilder);
            }
            ui.SetBlueprintSelected(isMobileLayout, index, true);
            ui.SetPickaxeSelected(false);
            RefreshLayoutTileHighlight();
        }
        private void SelectPickaxeAction()
        {
            if (IsHoldingAnything())
            {
                Global.Sounds.Play2D(LogicSoundID.tap);
                CancelHolding();
            }
            else
            {
                // TODO 实现这个
                //Global.Sounds.Play2D(VanillaSoundID.pickaxe);
                HoldPickaxe();
            }
        }
        private void HoldPickaxe()
        {
            holdingBlueprintIndex = -1;
            holdingPickaxe = true;
            // TODO 改为Vanilla。
            var modelBuilder = ModelFactories.GetModelBuilder(new NamespaceID("mvz2", "held.pickaxe"), GetCamera());
            if (modelBuilder != null)
            {
                ui.SetHoldingModel(modelBuilder);
            }
            ui.SetPickaxeSelected(true);
            RefreshLayoutTileHighlight();
        }
        private void CancelHolding()
        {
            if (holdingBlueprintIndex >= 0)
            {
                ui.SetBlueprintSelected(isMobileLayout, holdingBlueprintIndex, false);
            }
            if (holdingPickaxe)
            {
                ui.SetPickaxeSelected(false);
            }
            holdingBlueprintIndex = -1;
            holdingPickaxe = false;
            ui.ClearHoldingModel();
            RefreshLayoutTileHighlight();
        }
        #endregion

        #region 地块高光
        private void RefreshLayoutTileHighlight()
        {
            if (focusedLayoutTileIndex >= 0)
            {
                SetLayoutTileHighlight(focusedLayoutTileIndex, true);
            }
        }
        private void SetLayoutTileHighlight(int index, bool enter)
        {
            if (enter)
            {
                if (holdingBlueprintIndex >= 0 && holdingBlueprintIndex < contraptionEntries.Count)
                {
                    var entityId = contraptionEntries[holdingBlueprintIndex];
                    var entityDefinition = Global.Game.GetEntityDefinition(entityId);
                    if (entityDefinition != null)
                    {
                        if (CanPlaceContraptionAt(entityDefinition, index))
                        {
                            ui.SetLayoutTileHighlight(index, Color.green);
                        }
                        else
                        {
                            ui.SetLayoutTileHighlight(index, Color.red);
                        }
                        return;
                    }
                }
                else if (holdingPickaxe && currentTeleporterTeam != null)
                {
                    var tile = currentTeleporterTeam.GetTile(index);
                    if (tile != null && CanDigUpContraptionAt(index))
                    {
                        ui.SetLayoutTileHighlight(index, Color.green);
                    }
                    else
                    {
                        ui.SetLayoutTileHighlight(index, Color.red);
                    }
                    return;
                }
            }
            ui.SetLayoutTileHighlight(index, Color.clear);
        }
        private void SetFocusedLayoutTileIndex(int index)
        {
            SetLayoutTileHighlight(focusedLayoutTileIndex, false);
            focusedLayoutTileIndex = index;
            SetLayoutTileHighlight(focusedLayoutTileIndex, true);
        }
        #endregion

        #region 地块操作
        private void ConfirmOnLayoutTileAction(int index)
        {
            if (IsHoldingAnyBlueprint())
            {
                var entityId = contraptionEntries[holdingBlueprintIndex];
                var entityDefinition = Global.Game.GetEntityDefinition(entityId);
                if (entityDefinition == null)
                    return;
                if (CanPlaceContraptionAt(entityDefinition, index))
                {
                    PlaceContraption(entityDefinition, index);
                }
            }
            else if (IsHoldingPickaxe())
            {
                if (CanDigUpContraptionAt(index))
                {
                    DigUpContraption(index);
                }
            }
        }
        #endregion

        #region 放置器械
        private bool CanPlaceContraptionAt(EntityDefinition definition, int index)
        {
            if (currentTeleporterTeam == null)
                return false;
            var tile = currentTeleporterTeam.GetTile(index);
            if (tile != null)
            {
                var tileEntities = tile.GetEntities();
                if (tileEntities.Contains(definition.GetID()))
                    return false;
                var gridLayersToTake = definition.GetGridLayersToTake();
                if (gridLayersToTake != null && gridLayersToTake.Length > 0)
                {
                    foreach (var ent in tileEntities)
                    {
                        var existedDef = Global.Game.GetEntityDefinition(ent);
                        if (existedDef == null)
                            continue;
                        var entGridLayers = existedDef.GetGridLayersToTake();
                        if (entGridLayers != null && entGridLayers.Length > 0 && entGridLayers.Any(l => gridLayersToTake.Contains(l)))
                        {
                            return false;
                        }
                    }
                }
            }
            return true;
        }
        private void PlaceContraption(EntityDefinition definition, int index)
        {
            if (currentTeleporterTeam == null)
                return;
            var entityID = definition.GetID();
            currentTeleporterTeam.AddTileEntity(index, entityID);
            AddEnergyCost(definition.GetCost());

            var modelBuilder = GetEntityModelBuilder(definition);
            if (modelBuilder != null)
            {
                ui.AddTileEntity(index, entityID, modelBuilder);
            }
            CancelHolding();

            var placeSound = definition.GetPlaceSound();
            if (NamespaceID.IsValid(placeSound))
            {
                Global.Sounds.Play2D(placeSound);
            }
        }
        #endregion

        #region 挖掘器械
        private bool CanDigUpContraptionAt(int index)
        {
            if (currentTeleporterTeam == null)
                return false;
            var tile = currentTeleporterTeam.GetTile(index);
            if (tile == null)
                return false;
            return tile.GetEntities().Length > 0;
        }
        private void DigUpContraption(int index)
        {
            if (currentTeleporterTeam == null)
                return;
            var tile = currentTeleporterTeam.GetTile(index);
            if (tile == null)
                return;
            var tileEntities = tile.GetEntities();
            var tileEntityDefinitions = tileEntities.Select(e => Global.Game.GetEntityDefinition(e)).OfType<EntityDefinition>();
            var entityDefinition = tileEntityDefinitions.OrderByDescending(e => GetDigUpPriority(e)).FirstOrDefault();
            if (entityDefinition == null)
                return;
            var entityID = entityDefinition.GetID();
            currentTeleporterTeam.RemoveTileEntity(index, entityID);
            AddEnergyCost(-entityDefinition.GetCost());

            ui.RemoveTileEntity(index, entityID);
            CancelHolding();

            // TODO 实现这个
            //var deathSound = entityDefinition.GetDeathSound();
            //if (NamespaceID.IsValid(deathSound))
            //{
            //    Global.Sounds.Play2D(deathSound);
            //}
        }
        private int GetDigUpPriority(EntityDefinition entityDefinition)
        {
            // TODO 实现这个
            //var layersToTake = entityDefinition.GetGridLayersToTake();
            //if (layersToTake == null)
            //    return -1;
            //var maxLayerIndex = 
            return 0;
        }
        #endregion

        private void SetEnergyCost(int energy)
        {
            energyCost = energy;
            ui.SetEnergy(GetRemainingEnergy().ToString());
        }
        private void AddEnergyCost(int value)
        {
            SetEnergyCost(energyCost + value);
            UpdateBlueprints();
        }
        private int GetRemainingEnergy()
        {
            return MAX_ENERGY - energyCost;
        }
        private Camera GetCamera()
        {
            if (uiCamera.Exists())
                return uiCamera;
            return Camera.main;
        }
        private IModelBuilder? GetEntityModelBuilder(EntityDefinition definition)
        {
            var modelID = definition.GetModelID();
            return ModelFactories.GetModelBuilder(modelID, GetCamera());
        }
        public static TeleporterTeam CreateDefaultTeleporterTeam()
        {
            // TODO: 改为Teleporter_Evoke。
            var team = new TeleporterTeam();
            team.AddTileEntity(1, new NamespaceID("mvz2", "furnace"));
            team.AddTileEntity(3, new NamespaceID("mvz2", "furnace"));
            team.AddTileEntity(5, new NamespaceID("mvz2", "furnace"));
            team.AddTileEntity(7, new NamespaceID("mvz2", "furnace"));
            return team;
        }

        public static MainManager Main => MainManager.Instance;
        public const int MAX_TILE_COUNT = 9;
        public const int MAX_ENERGY = 250;
        public static readonly TeleporterTeam DefaultTeam = CreateDefaultTeleporterTeam(); // TODO: 改为Teleporter_Evoke。
        [SerializeField]
        private TeleporterTeamUI ui = null!;
        private Camera? uiCamera;
        private TeleporterTeam? currentTeleporterTeam;
        private int energyCost = 0;
        private int holdingBlueprintIndex = -1;
        private bool holdingPickaxe;
        private int focusedLayoutTileIndex = -1;
        private bool dragBlueprintStarted;
        private int draggingTargetBlueprintIndex = -1;
        private bool isMobileLayout;
        private readonly List<NamespaceID?> contraptionEntries = new List<NamespaceID?>();
    }
}
